require_once __DIR__.'/includes/auth.php';require_login();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE notifications SET read_at=NOW() WHERE id=? AND user_id=?')->execute([(int)$_POST['id'],current_user()['id']]);audit_action('notification_read','notifications',(int)$_POST['id']);redirect('notifications.php');}$items=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 100');$items->execute([current_user()['id']]);$items=$items->fetchAll();$pageTitle='Notifications';$activePage='notifications';require __DIR__.'/partials/header.php';
?><section class="section-heading"><div><div class="eyebrow">Inbox / System updates</div><h1>Notifications</h1><p>Track service updates, account events, and security messages.</p></div></section><section class="panel table-panel"><div class="portal-list"><?php foreach($items as $item): ?><div class="portal-row <?= $item['read_at']?'':'unread' ?>"><div><strong><?= h($item['title']) ?></strong><small><?= h($item['message']) ?> · <?= h(date('M d, Y h:i A',strtotime($item['created_at']))) ?></small></div><?php if(!$item['read_at']): ?><form method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id" value="<?= h($item['id']) ?>"><button class="text-button">Mark read</button></form><?php endif; ?></div><?php endforeach; ?><?php if(!$items): ?><p class="empty-state">No notifications yet.</p><?php endif; ?></div></section><?php require __DIR__.'/partials/footer.php'; ?>
